-- -----------------------------------------------------------------
-- 0. Ensure all referenced chapters exist (no leader assigned)
--    Safe to run against a DB that already has some chapters;
--    only inserts rows whose code is not yet present.
-- -----------------------------------------------------------------
SELECT v.name, v.code, 'active', NOW(), NOW()
FROM (VALUES
    ('Arab Academy For Science, Technology & Maritime Transport - Aswan', 'AASMTA'),
    ('Arab Academy for Science Technology and Maritime Transport - Cairo', 'AASTMT'),
    ('Assiut University',                                'AU'),
    ('Al-Azhar',                                        'AZHR'),
    ('Benha National University',                       'BNU'),
    ('Canadian International College',                  'CIC'),
    ('Damanhour University',                            'DMU'),
    ('Future Academy',                                  'FA'),
    ('Galala University',                               'GU'),
    ('Hurghada University',                             'HU'),
    ('Modern Academy CS',                               'MACS'),
    ('Modern University for Technology and Information','MTI'),
    ('Misr University for Science and Technology',      'MUST'),
    ('New Cairo Technological University',              'NCTU'),
    ('Obour Institute',                                 'OI'),
    ('Suez Canal University',                           'SCU'),
    ('South Valley University',                         'SVU')
) AS v(name, code)
WHERE NOT EXISTS (
    SELECT 1 FROM chapters WHERE upper(code) = upper(v.code) AND deleted_at IS NULL
);

-- -----------------------------------------------------------------
-- 1. Placeholder templates (idempotent - skip if name already exists)
-- -----------------------------------------------------------------
DO $$
DECLARE
    v_owner_user_id    UUID;
    v_owner_chapter_id UUID;
    v_tmpl_id          UUID;
    v_ver_id           UUID;
    v_slug             TEXT;
BEGIN
    -- Grab any existing user+chapter pair to satisfy NOT NULL FKs
    SELECT u.id, u.chapter_id
    INTO   v_owner_user_id, v_owner_chapter_id
    FROM   users u
    WHERE  u.chapter_id IS NOT NULL
    LIMIT  1;

    IF v_owner_user_id IS NULL THEN
        RAISE EXCEPTION 'No users with a chapter_id found - cannot create placeholder templates';
    END IF;

    v_slug := 'gdgoc-25.blue';
    IF NOT EXISTS (SELECT 1 FROM templates WHERE name = v_slug AND deleted_at IS NULL) THEN
        v_tmpl_id := gen_random_uuid();
        v_ver_id  := gen_random_uuid();
                               visibility, status, created_at, updated_at)
        VALUES (v_tmpl_id, v_slug, 'Legacy import placeholder',
                v_owner_user_id, v_owner_chapter_id, 'public', 'published', NOW(), NOW());
        VALUES (v_ver_id, v_tmpl_id, 1, '{}', NOW());
        UPDATE templates SET current_version_id = v_ver_id WHERE id = v_tmpl_id;
    END IF;

    v_slug := 'gdgoc-25.green';
    IF NOT EXISTS (SELECT 1 FROM templates WHERE name = v_slug AND deleted_at IS NULL) THEN
        v_tmpl_id := gen_random_uuid();
        v_ver_id  := gen_random_uuid();
                               visibility, status, created_at, updated_at)
        VALUES (v_tmpl_id, v_slug, 'Legacy import placeholder',
                v_owner_user_id, v_owner_chapter_id, 'public', 'published', NOW(), NOW());
        VALUES (v_ver_id, v_tmpl_id, 1, '{}', NOW());
        UPDATE templates SET current_version_id = v_ver_id WHERE id = v_tmpl_id;
    END IF;

    v_slug := 'gdgoc-25.red';
    IF NOT EXISTS (SELECT 1 FROM templates WHERE name = v_slug AND deleted_at IS NULL) THEN
        v_tmpl_id := gen_random_uuid();
        v_ver_id  := gen_random_uuid();
                               visibility, status, created_at, updated_at)
        VALUES (v_tmpl_id, v_slug, 'Legacy import placeholder',
                v_owner_user_id, v_owner_chapter_id, 'public', 'published', NOW(), NOW());
        VALUES (v_ver_id, v_tmpl_id, 1, '{}', NOW());
        UPDATE templates SET current_version_id = v_ver_id WHERE id = v_tmpl_id;
    END IF;

    v_slug := 'gdgoc-25.yellow';
    IF NOT EXISTS (SELECT 1 FROM templates WHERE name = v_slug AND deleted_at IS NULL) THEN
        v_tmpl_id := gen_random_uuid();
        v_ver_id  := gen_random_uuid();
                               visibility, status, created_at, updated_at)
        VALUES (v_tmpl_id, v_slug, 'Legacy import placeholder',
                v_owner_user_id, v_owner_chapter_id, 'public', 'published', NOW(), NOW());
        VALUES (v_ver_id, v_tmpl_id, 1, '{}', NOW());
        UPDATE templates SET current_version_id = v_ver_id WHERE id = v_tmpl_id;
    END IF;

END $$;

